INSERT INTO `state_descriptions` (`id`, `state_id`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 'Aguascalientes tenía una población de 463.3 mil personas de 0 a 17 años en 2020, lo que representaba 32.5% de la población total. 0.1% era indígena, 1.3% afrodescendiente y 6.9% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(2, 2, 'Baja California tenía una población de 1.1 millones de personas de 0 a 17 años en 2020, lo que representaba 28.2% de la población total. 0.6% era indígena, 1.3% afrodescendiente y 6.9% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(3, 3, 'Baja California Sur tenía una población de 236.6 mil personas de 0 a 17 años en 2020, lo que representaba 29.6% de la población total. 0.5% era indígena, 2.9% afrodescendiente y 7.3% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(4, 4, 'Campeche tenía una población de 286.9 mil personas de 0 a 17 años en 2020, lo que representaba 30.9% de la población total. 4.1% era indígena, 1.7% afrodescendiente y 7.6% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(5, 5, 'Chiapas tenía una población de 2.1 millones de personas de 0 a 17 años en 2020, lo que representaba 37.8% de la población total. 31.6% era indígena, 0.8% afrodescendiente y 5% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(6, 6, 'Chihuahua tenía una población de 1.1 millones de personas de 0 a 17 años en 2020, lo que representaba 30.4% de la población total. 3.6% era indígena, 1.3% afrodescendiente y 6.7% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(7, 7, 'Ciudad de México tenía una población de 2 millones de personas de 0 a 17 años en 2020, lo que representaba 22.1% de la población total. 0.4% era indígena, 1.5% afrodescendiente y 7.8% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(8, 8, 'Coahuila tenía una población de 982.8 mil personas de 0 a 17 años en 2020, lo que representaba 31.2% de la población total. 0.04% era indígena, 1.1% afrodescendiente y 5.7% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
(9, 9, 'Colima tenía una población de 209.4 mil personas de 0 a 17 años en 2020, lo que representaba 28.6% de la población total. 0.6% era indígena, 1.5% afrodescendiente y 7.1% tenía una discapacidad (INEGI, Censo 2020).', 1, '2026-07-29 07:13:25', '2026-07-29 07:13:25'),
