INSERT INTO `help_contacts` (`id`, `name`, `description`, `phone`, `phone_alt`, `email`, `social_text`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'LÍNEA NACIONAL CONTRA LA TRATA DE PERSONAS', 'Atención gratuita, confidencial y disponible las 24 horas para orientación, denuncia y acompañamiento. <strong>También cuenta con servicio de chat.</strong>', '800 5533 000', NULL, NULL, NULL, 1, 1, '2026-07-29 05:16:30', '2026-07-29 05:39:42'),
(2, 'Consejo Ciudadano para la Seguridad y Justicia de la Ciudad de México', 'Atención 24/7 para orientación psicológica y jurídica, incluida la Línea Nacional contra la Trata, además de canalización especializada.', '55 5533 5533', NULL, NULL, NULL, 2, 1, '2026-07-29 05:16:30', '2026-07-29 05:39:42'),
(3, 'Centro de Atención Ciudadana (CEDAC) · FEVIMTRA', 'Fiscalía Especializada en Delitos de Violencia contra las Mujeres, Grupos en Situación de Vulnerabilidad y Trata de Personas. Recibe denuncias e investiga delitos federales relacionados con trata de personas y violencia contra niñas, niños y adolescentes.', '(55) 5346 4249', NULL, 'fevimtra@fgr.org.mx', NULL, 3, 1, '2026-07-29 05:16:30', '2026-07-29 05:39:42'),
(4, 'Alerta AMBER México', 'Si una niña, niño o adolescente desaparece, el reporte debe hacerse de inmediato; no es necesario esperar 24, 48 o 72 horas.', '(55) 5346 2516', '800 00 854 00', 'alertaamber@fgr.org.mx', 'X: @AAMBER_mx · Facebook: Alerta AMBER México Oficial', 4, 1, '2026-07-29 05:16:30', '2026-07-29 05:43:28');
